static void rp_print(u64 v) {
  char buf[24];
  int i = 22;
  buf[23] = 10;
  do { buf[i--] = (char)('0' + (v % 10)); v /= 10; } while (v);
#if RP_OS_WIN32
  (void)_write(1, buf + i + 1, (unsigned)(23 - i));
#else
  (void)write(1, buf + i + 1, (size_t)(23 - i));
#endif
}

