int main(int argc, char **argv, char **envp) {
#if RP_OS_WIN32
  /* Porth writes raw newlines; keep the CRT from rewriting them. */
  _setmode(_fileno(stdin), _O_BINARY);
  _setmode(_fileno(stdout), _O_BINARY);
  _setmode(_fileno(stderr), _O_BINARY);
#endif
  rp_argc = argc;
  rp_argv = argv;
  rp_envp = envp;
  rp_run(52565ULL);
  return 0;
}
